// FreeLang v2.0 Memory Engine - 자율 생명주기 추론
console.log("\n" + "=".repeat(60))
console.log("FreeLang v2.0 Memory Engine - 자율 생명주기 추론")
console.log("=".repeat(60))

class LifetimeAnalyzer {
  variables: Map<string, { allocated: number; freed: number; lifetime: number }>

  constructor() {
    this.variables = new Map()
  }

  allocate(name: string) {
    const now = Date.now()
    this.variables.set(name, { allocated: now, freed: 0, lifetime: 0 })
    console.log(`✓ Allocate: ${name}`)
  }

  // 자율적으로 생명주기 추론
  infer_lifetime(name: string): number {
    const data = this.variables.get(name)
    if (!data) return 0
    // 추론: 마지막 접근까지의 시간
    return Date.now() - data.allocated
  }

  // 자동으로 필요없는 변수 해제
  auto_deallocate(name: string) {
    const lifetime = this.infer_lifetime(name)
    this.variables.set(name, {
      ...this.variables.get(name)!,
      freed: Date.now(),
      lifetime
    })
    console.log(`✓ Auto-dealloc: ${name} (lifetime: ${lifetime}ms)`)
  }
}

// 테스트
