fn test_and_basic() {
    // PUSH 12 (0b1100), PUSH 10 (0b1010), AND
    // Expected: 8 (0b1000)
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D,  // Magic
        0x01, 0x00,              // Version
        0x00, 0x00,              // Flags
        0x00, 0x00, 0x00, 0x13,  // Code size: 19
        0x00, 0x00, 0x00, 0x10,  // Code offset: 16
        // PUSH 12
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0C,
        // PUSH 10
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A,
