fn test_loop_basic() {
    // PUSH 3, (loop:) INCR, LOOP(loop), HALT 0
    // Expected: counter decreases to 0
}

#[test]
fn test_loop_zero() {
    // PUSH 0, LOOP(target), PUSH 10, (target:) HALT 0
    // Expected: LOOP not executed, 10 pushed
}
```

### CMPJMP 테스트
```rust
