// ====== Control Flow Instructions Tests ======

#[test]
fn test_jmp_basic() {
    // PUSH 10, JMP(to skip), PUSH 20, (skip:), HALT 0
    // Expected: only 10 on stack (20 skipped)
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, // Magic: FLVM
        0x01, 0x00,             // Version
        0x00, 0x00,             // Flags
        0x00, 0x00, 0x00, 0x2B, // Code size: 43 bytes
        0x00, 0x00, 0x00, 0x10, // Code offset: 16
        // Code
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A, // PUSH 10
        0x30, 0x00, 0x00, 0x00, 0x1C,                         // JMP 28 (skip PUSH 20)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x14, // PUSH 20
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 1);
    assert_eq!(vm.memory.read(0).unwrap(), 10);
}

#[test]
fn test_jif_false() {
    // PUSH 0, JIF(skip), PUSH 10, (skip:), HALT 0
    // Expected: only 0 on stack (10 skipped)
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x29, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // PUSH 0
        0x31, 0x00, 0x00, 0x00, 0x22,                         // JIF 34 (jump)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A, // PUSH 10
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 1);
    assert_eq!(vm.memory.read(0).unwrap(), 0);
}

#[test]
fn test_jif_true() {
    // PUSH 1, JIF(skip), PUSH 10, HALT 0, (skip:), HALT 0
    // Expected: both 1 and 10 on stack (no jump)
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x2C, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, // PUSH 1
        0x31, 0x00, 0x00, 0x00, 0x25,                         // JIF (no jump)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A, // PUSH 10
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 2);
    assert_eq!(vm.memory.read(0).unwrap(), 1);
    assert_eq!(vm.memory.read(1).unwrap(), 10);
}

#[test]
fn test_jit_true() {
    // PUSH 1, JIT(skip), PUSH 10, (skip:), HALT 0
    // Expected: only 1 on stack (10 skipped)
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x29, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, // PUSH 1
        0x32, 0x00, 0x00, 0x00, 0x22,                         // JIT 34 (jump)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A, // PUSH 10
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 1);
    assert_eq!(vm.memory.read(0).unwrap(), 1);
}

#[test]
fn test_jit_false() {
    // PUSH 0, JIT(skip), PUSH 10, HALT 0, (skip:), HALT 0
    // Expected: both 0 and 10 on stack (no jump)
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x2C, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // PUSH 0
        0x32, 0x00, 0x00, 0x00, 0x25,                         // JIT (no jump)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A, // PUSH 10
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 2);
    assert_eq!(vm.memory.read(0).unwrap(), 0);
    assert_eq!(vm.memory.read(1).unwrap(), 10);
}

#[test]
fn test_call_ret_basic() {
    // CALL(func), PUSH 100, HALT 0, (func:) PUSH 42, RET
    // Expected: 42 then 100 on stack
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x35, 0x00, 0x00, 0x00, 0x10,
        0x33, 0x00, 0x00, 0x00, 0x25,                         // CALL 37 (func)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x64, // PUSH 100
        0x61, 0x00,                                             // HALT 0
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x2A, // PUSH 42
        0x34,                                                   // RET
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 2);
    assert_eq!(vm.memory.read(0).unwrap(), 42);
    assert_eq!(vm.memory.read(1).unwrap(), 100);
}

#[test]
fn test_call_ret_nested() {
    // CALL(outer), HALT, (outer:) CALL(inner), RET, (inner:) PUSH 7, RET
    // Expected: nested calls work correctly
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x3A, 0x00, 0x00, 0x00, 0x10,
        0x33, 0x00, 0x00, 0x00, 0x1F,                         // CALL outer (31)
        0x61, 0x00,                                             // HALT
        0x33, 0x00, 0x00, 0x00, 0x32,                         // CALL inner (50)
        0x34,                                                   // RET
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x07, // PUSH 7
        0x34,                                                   // RET
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert!(vm.sp >= 1);
    assert_eq!(vm.memory.read(0).unwrap(), 7);
}

#[test]
fn test_loop_basic() {
    // PUSH 3, (loop:) INCR, DUP, PUSH 3, CMPJMP(loop), HALT 0
    // Loop decrements from 3 to 0
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x3D, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x03, // PUSH 3
        0x35, 0x00, 0x00, 0x00, 0x1C,                         // LOOP 28
        0x17,                                                   // INCR
        0x07,                                                   // DUP
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    // After loop executes, counter should be 0 or decrement
    assert!(vm.sp >= 1);
}

#[test]
fn test_loop_zero() {
    // PUSH 0, LOOP(target), PUSH 10, (target:) HALT 0
    // LOOP should not execute when counter is 0
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x2A, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // PUSH 0
        0x35, 0x00, 0x00, 0x00, 0x23,                         // LOOP 35
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A, // PUSH 10
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 2);
    assert_eq!(vm.memory.read(0).unwrap(), 0);
    assert_eq!(vm.memory.read(1).unwrap(), 10);
}

#[test]
fn test_cmpjmp_equal() {
    // PUSH 5, PUSH 5, CMPJMP(skip), PUSH 10, (skip:) HALT 0
    // Expected: 5 only (10 skipped)
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x34, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x05, // PUSH 5
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x05, // PUSH 5
        0x36, 0x00, 0x00, 0x00, 0x2B,                         // CMPJMP 43
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A, // PUSH 10
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 1);
    assert_eq!(vm.memory.read(0).unwrap(), 5);
}

#[test]
fn test_cmpjmp_not_equal() {
    // PUSH 5, PUSH 6, CMPJMP(skip), PUSH 10, HALT 0, (skip:) HALT 0
    // Expected: 5, 6, 10 (no jump)
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x37, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x05, // PUSH 5
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x06, // PUSH 6
        0x36, 0x00, 0x00, 0x00, 0x2E,                         // CMPJMP (no jump)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A, // PUSH 10
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 3);
    assert_eq!(vm.memory.read(0).unwrap(), 5);
    assert_eq!(vm.memory.read(1).unwrap(), 6);
    assert_eq!(vm.memory.read(2).unwrap(), 10);
}

#[test]
fn test_nop_basic() {
    // PUSH 42, NOP, NOP, HALT 0
    // Expected: 42 (NOPs do nothing)
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x1A, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x2A, // PUSH 42
        0x37,                                                   // NOP
        0x37,                                                   // NOP
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 1);
    assert_eq!(vm.memory.read(0).unwrap(), 42);
}

#[test]
fn test_control_flow_if_else() {
    // if-else pattern: PUSH 10, PUSH 5, LT, JIT(else), PUSH 100, JMP(end),
    // (else:) PUSH 200, (end:) HALT 0
    // 10 < 5 is false, so else branch executes
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x3C, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A, // PUSH 10
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x05, // PUSH 5
        0x26,                                                   // LT
        0x32, 0x00, 0x00, 0x00, 0x31,                         // JIT 49 (else)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x64, // PUSH 100
        0x30, 0x00, 0x00, 0x00, 0x35,                         // JMP 53 (end)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xC8, // PUSH 200
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    // Should have 200 (else branch)
    assert_eq!(vm.sp, 1);
    assert_eq!(vm.memory.read(0).unwrap(), 200);
}

