#[test]
fn test_arralloc_basic() {
    // PUSH 5, ARRALLOC, (store array address)
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x1A, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x05, // PUSH 5
        0x40,                                                   // ARRALLOC
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 1);
    // Array should be allocated at heap start (0x5000)
    assert_eq!(vm.memory.read(0x5000).unwrap(), 5); // length = 5
}

#[test]
fn test_arrlen_basic() {
    // PUSH 7, ARRALLOC, ARRLEN
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x1C, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x07, // PUSH 7
        0x40,                                                   // ARRALLOC
