}

#[test]
fn test_arrset_arrget_basic() {
    // PUSH 3, ARRALLOC, (arr), PUSH 100, PUSH 0, ARRSET
    // PUSH 0, ARRGET
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x45, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x03, // PUSH 3
        0x40,                                                   // ARRALLOC -> array at 0x5000
        0x07,                                                   // DUP
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x64, // PUSH 100
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // PUSH 0 (index)
        0x42,                                                   // ARRSET -> arr[0] = 100
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // PUSH 0 (index)
        0x41,                                                   // ARRGET -> read arr[0]
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 1);
    assert_eq!(vm.memory.read(0).unwrap(), 100);
}

