    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D,  // Magic
        0x01, 0x00,              // Version
        0x00, 0x00,              // Flags
        0x00, 0x00, 0x00, 0x0A,  // Code size: 10
        0x00, 0x00, 0x00, 0x10,  // Code offset: 16
        // PUSH -42 (as u64 = 0xFFFFFFFFFFFFFFD6)
        0x01, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xD6,
        // ABS
        0x16,
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    vm.step().unwrap();  // PUSH -42
    vm.step().unwrap();  // ABS
    assert_eq!(vm.sp, 1);
