#[test]
fn test_logic_complex() {
    // PUSH 5, PUSH 10, LT (true=1)
    // PUSH 3, PUSH 3, EQ (true=1)
    // AND (1 & 1 = 1)
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D,  // Magic
        0x01, 0x00,              // Version
        0x00, 0x00,              // Flags
        0x00, 0x00, 0x00, 0x23,  // Code size: 35
        0x00, 0x00, 0x00, 0x10,  // Code offset: 16
        // PUSH 5
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x05,
        // PUSH 10
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A,
        // LT
        0x26,
        // PUSH 3
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x03,
        // PUSH 3
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x03,
        // EQ
        0x24,
        // AND
        0x20,
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    vm.step().unwrap();  // PUSH 5
    vm.step().unwrap();  // PUSH 10
    vm.step().unwrap();  // LT (5 < 10 = 1)
    vm.step().unwrap();  // PUSH 3
    vm.step().unwrap();  // PUSH 3
    vm.step().unwrap();  // EQ (3 == 3 = 1)
    vm.step().unwrap();  // AND (1 & 1 = 1)
    assert_eq!(vm.sp, 1);
    assert_eq!(vm.memory.read(0).unwrap(), 1);
}

