/// Garbage Collection System for FreeLang VM
/// Implements Mark-and-Sweep garbage collection algorithm

use std::collections::HashSet;

#[derive(Debug, Clone)]
pub struct HeapObject {
    pub address: usize,
    pub size: u64,
    pub allocated: bool,
    pub marked: bool,
    pub object_type: ObjectType,
}

#[derive(Debug, Clone)]
pub enum ObjectType {
    Array(u64),   // element count
    String(u64),  // length in bytes
}

#[derive(Debug, Clone)]
pub struct GCStats {
    pub collections: u64,
    pub objects_freed: u64,
    pub total_freed_bytes: u64,
    pub collection_time_ms: f64,
}

pub struct GarbageCollector {
    pub heap_objects: Vec<HeapObject>,
    free_list: Vec<usize>,
    pub gc_stats: GCStats,
}

impl GarbageCollector {
    pub fn new() -> Self {
        GarbageCollector {
            heap_objects: Vec::new(),
            free_list: Vec::new(),
            gc_stats: GCStats {
                collections: 0,
                objects_freed: 0,
                total_freed_bytes: 0,
                collection_time_ms: 0.0,
            },
        }
    }

    /// Register a new heap allocation
    pub fn register_allocation(&mut self, address: usize, size: u64, obj_type: ObjectType) {
        let obj = HeapObject {
            address,
            size,
            allocated: true,
            marked: false,
            object_type,
        };
        self.heap_objects.push(obj);
    }

    /// Mark phase: Mark all reachable objects
    pub fn mark_reachable(&mut self, stack: &[u64], globals: &[u64]) {
        // Clear all marks
        for obj in &mut self.heap_objects {
            obj.marked = false;
        }

        let mut to_visit = Vec::new();

        // Add roots (stack + globals)
        for &value in stack {
            if self.is_heap_pointer(value) {
                to_visit.push(value as usize);
            }
        }

        for &value in globals {
            if self.is_heap_pointer(value) {
                to_visit.push(value as usize);
            }
        }

        // Remove duplicates
        to_visit.sort();
        to_visit.dedup();

        // DFS traversal
        let mut visited = HashSet::new();
        while let Some(addr) = to_visit.pop() {
            if visited.contains(&addr) {
                continue;
            }
            visited.insert(addr);

            if let Some(obj) = self.find_object_mut(addr) {
                obj.marked = true;

                // For arrays with pointers, scan for more pointers
                // (In simple implementation, assume arrays may contain pointers)
                if let ObjectType::Array(_size) = obj.object_type {
                    // In a full implementation, we would:
                    // 1. Read each element from heap
                    // 2. Check if it's a heap pointer
                    // 3. Add to to_visit if not visited
                    // For now, simple array tracking is sufficient
                }
            }
        }
    }

    /// Sweep phase: Reclaim unmarked objects
    pub fn sweep(&mut self) {
        let mut freed_count = 0;
        let mut freed_bytes: u64 = 0;

        for obj in &mut self.heap_objects {
            if !obj.allocated {
                continue; // Already free
            }

            if !obj.marked {
                obj.allocated = false;
                freed_count += 1;
                freed_bytes += obj.size;
                self.free_list.push(obj.address);
            }
        }

        // Update statistics
        self.gc_stats.collections += 1;
        self.gc_stats.objects_freed += freed_count;
        self.gc_stats.total_freed_bytes += freed_bytes;
    }

    /// Run complete GC cycle (mark + sweep)
    pub fn collect(&mut self, stack: &[u64], globals: &[u64]) {
        let start = std::time::Instant::now();

        self.mark_reachable(stack, globals);
        self.sweep();

        let elapsed = start.elapsed().as_secs_f64() * 1000.0; // Convert to ms
        self.gc_stats.collection_time_ms = elapsed;
    }

    /// Get total allocated heap size
    pub fn allocated_bytes(&self) -> u64 {
        self.heap_objects
            .iter()
            .filter(|obj| obj.allocated)
            .map(|obj| obj.size)
            .sum()
    }

    /// Get total heap size
    pub fn total_heap_bytes(&self) -> u64 {
        self.heap_objects.iter().map(|obj| obj.size).sum()
    }

    /// Check if a value looks like a heap pointer
    fn is_heap_pointer(&self, value: u64) -> bool {
        let addr = value as usize;
        // Heap range: 0x5000 - 0xFFFD
        addr >= 0x5000 && addr <= 0xFFFD
    }

    /// Find object by address (mutable)
    fn find_object_mut(&mut self, addr: usize) -> Option<&mut HeapObject> {
        self.heap_objects.iter_mut().find(|obj| obj.address == addr)
    }

    /// Find object by address (immutable)
    pub fn find_object(&self, addr: usize) -> Option<&HeapObject> {
        self.heap_objects.iter().find(|obj| obj.address == addr)
    }

    /// Get GC statistics
    pub fn stats(&self) -> &GCStats {
        &self.gc_stats
    }

    /// Get count of allocated objects
    pub fn allocated_objects_count(&self) -> usize {
        self.heap_objects.iter().filter(|obj| obj.allocated).count()
    }

    /// Print GC stats (debug)
    pub fn print_stats(&self) {
        println!("=== GC Statistics ===");
        println!("Collections: {}", self.gc_stats.collections);
        println!("Objects Freed: {}", self.gc_stats.objects_freed);
        println!("Total Freed Bytes: {}", self.gc_stats.total_freed_bytes);
        println!("Collection Time: {:.2}ms", self.gc_stats.collection_time_ms);
        println!("Current Objects: {}", self.allocated_objects_count());
        println!("Allocated Bytes: {}", self.allocated_bytes());
    }
}

impl Default for GarbageCollector {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

