//! Unit tests for FreeLang VM
//!
//! Tests individual VM components and instructions

use freelang_vm::vm::VM;
use freelang_vm::bytecode::{BytecodeLoader, Opcode};
use freelang_vm::memory::Memory;
use freelang_vm::gc::GarbageCollector;

// ====== Bytecode Loader Tests ======

#[test]
fn test_bytecode_loader_valid_empty_program() {
    // Valid bytecode with HALT instruction
    let data = vec![
        0x46, 0x4C, 0x56, 0x4D, // Magic: FLVM
        0x01, 0x00,             // Version: 0x0100
        0x00, 0x00,             // Flags: 0x0000
        0x00, 0x00, 0x00, 0x01, // Code size: 1
        0x00, 0x00, 0x00, 0x10, // Code offset: 16
        0x61,                   // HALT opcode
    ];

    let loader = BytecodeLoader::new(&data);
    assert!(loader.is_ok());
}

#[test]
fn test_bytecode_loader_invalid_magic() {
    let data = vec![
        0xFF, 0xFF, 0xFF, 0xFF, // Invalid magic
        0x01, 0x00,
        0x00, 0x00,
        0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x10,
    ];

    let loader = BytecodeLoader::new(&data);
    assert!(loader.is_err());
}

#[test]
fn test_bytecode_loader_too_small() {
    let data = vec![0x01, 0x02, 0x03];
    let loader = BytecodeLoader::new(&data);
    assert!(loader.is_err());
}

// ====== Opcode Tests ======

    // Test combining: Load/Store, Arithmetic, Logic, Control Flow, Array, String
    // Create array, create string, do arithmetic, conditional logic
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x5F, 0x00, 0x00, 0x00, 0x10,
        // Array: create and set
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x02, // PUSH 2
        0x40,                                                   // ARRALLOC
        0x08,                                                   // SWAP
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A, // PUSH 10
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // PUSH 0
        0x42,                                                   // ARRSET
        // String: create and set
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x02, // PUSH 2
        0x50,                                                   // STRALLOC
        0x08,                                                   // SWAP
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x41, // PUSH 65 ('A')
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // PUSH 0
        0x52,                                                   // STRSET
        // Arithmetic: 5 + 5 = 10
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x05, // PUSH 5
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x05, // PUSH 5
        0x10,                                                   // ADD
        // Logic: 10 > 5 => 1
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x05, // PUSH 5
        0x26,                                                   // LT (10 < 5 = 0)
        0x22,                                                   // NOT (result = 1)
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    // Verify at least one result on stack
    assert!(vm.sp >= 1);
}

