    assert_eq!(vm.sp, 1);
    assert_eq!(vm.memory.read(0).unwrap(), 30);
}

#[test]
fn test_add_overflow() {
    // PUSH u64::MAX, PUSH 1, ADD (should wrap)
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D,  // Magic
        0x01, 0x00,              // Version
        0x00, 0x00,              // Flags
        0x00, 0x00, 0x00, 0x13,  // Code size: 19
        0x00, 0x00, 0x00, 0x10,  // Code offset: 16
        // PUSH u64::MAX
        0x01, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF,
        // PUSH 1
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01,
        // ADD
        0x10,
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    vm.step().unwrap();  // PUSH u64::MAX
    vm.step().unwrap();  // PUSH 1
