#[test]
fn test_integrated_arithmetic_logic() {
    // (10 + 20) > 15 => 30 > 15 => 1 (true)
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x33, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A, // PUSH 10
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x14, // PUSH 20
        0x10,                                                   // ADD -> 30
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0F, // PUSH 15
        0x26,                                                   // LT (30 < 15 = 0, but we want 30 > 15)
        0x22,                                                   // NOT to flip
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 1);
    assert_eq!(vm.memory.read(0).unwrap(), 1); // true
}

