#[test]
fn test_integrated_if_else_with_variables() {
    // if (1 > 0) { PUSH 100 } else { PUSH 50 }
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x37, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, // PUSH 1
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // PUSH 0
        0x26,                                                   // LT (1 < 0 = 0)
        0x32, 0x00, 0x00, 0x00, 0x29,                         // JIT 41 (jump to else if true)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x64, // PUSH 100 (then)
        0x30, 0x00, 0x00, 0x00, 0x2D,                         // JMP 45 (skip else)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x32, // PUSH 50 (else)
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 1);
    // 1 < 0 is false, so JIT doesn't jump, we execute PUSH 100
    assert_eq!(vm.memory.read(0).unwrap(), 100);
}

