        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x1E, // PUSH 30 (element 3)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x02, // PUSH 2
        0x42,                                                   // ARRSET
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // PUSH 0 (sum = 0)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // PUSH 0 (index = 0)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x03, // PUSH 3 (count)
        0x35, 0x00, 0x00, 0x00, 0x58,                         // LOOP back (iterate)
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    // Basic test: loop mechanism works
    assert!(vm.sp >= 1);
}

