#[test]
fn test_heap_usage_improvement() {
    use freelang_vm::gc::ObjectType;

    let mut gc = GarbageCollector::new();
    gc.register_allocation(0x5000, 10, ObjectType::Array(5));
    gc.register_allocation(0x500B, 5, ObjectType::String(3));
    gc.register_allocation(0x5010, 8, ObjectType::Array(4));

    let allocated_before = gc.allocated_bytes();

    // Free middle object
    let stack = [0x5000, 0x5010];
    gc.mark_reachable(&stack, &[]);
    gc.sweep();

    let mut stack_mut = [0x5000, 0x5010];
    let mut globals: [u64; 0] = [];
    gc.compact(&mut stack_mut, &mut globals);

    let allocated_after = gc.allocated_bytes();

    // Verify heap is compacted (though allocation amount same, layout is better)
    assert!(allocated_after <= allocated_before);
}

