fn test_vm_pc_increment() {
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, // Magic
        0x01, 0x00,             // Version
        0x00, 0x00,             // Flags
        0x00, 0x00, 0x00, 0x01, // Code size
        0x00, 0x00, 0x00, 0x10, // Code offset
        0x61,                   // HALT
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    assert_eq!(vm.pc, 0);

    // PC increments during step (before we implement actual instructions)
    // For now, this will fail with "not implemented"
