        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // PUSH 0
        0x26,                                                   // LT (1 < 0 = 0)
        0x32, 0x00, 0x00, 0x00, 0x29,                         // JIT 41 (jump to else if true)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x64, // PUSH 100 (then)
        0x30, 0x00, 0x00, 0x00, 0x2D,                         // JMP 45 (skip else)
