    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 1);
    // 1 < 0 is false, so JIT doesn't jump, we execute PUSH 100
    assert_eq!(vm.memory.read(0).unwrap(), 100);
}

