#[test]
fn test_compaction_basic() {
    use freelang_vm::gc::ObjectType;

    let mut gc = GarbageCollector::new();
    gc.register_allocation(0x5000, 5, ObjectType::Array(5));
    gc.register_allocation(0x5006, 3, ObjectType::String(3));
    gc.register_allocation(0x5009, 7, ObjectType::Array(7));

    // Simulate fragmentation: free middle object
    let stack = [0x5000, 0x5009];
    gc.mark_reachable(&stack, &[]);
    gc.sweep();

    // Before compaction: [Array1(5)] [FREE(3)] [Array2(7)]
    // After compaction: [Array1(5)] [Array2(7)]
    let mut stack_mut = [0x5000, 0x5009];
    let mut globals: [u64; 0] = [];
    gc.compact(&mut stack_mut, &mut globals);

    // Verify references updated
    assert_eq!(stack_mut[0], 0x5000); // Array1 stays at 0x5000
    assert_eq!(stack_mut[1], 0x5005); // Array2 moved from 0x5009 to 0x5005
}

