//! Unit tests for FreeLang VM
//!
//! Tests individual VM components and instructions

use freelang_vm::vm::VM;
use freelang_vm::bytecode::{BytecodeLoader, Opcode};
use freelang_vm::memory::Memory;
use freelang_vm::gc::GarbageCollector;

// ====== Bytecode Loader Tests ======

#[test]
fn test_bytecode_loader_valid_empty_program() {
    // Valid bytecode with HALT instruction
    let data = vec![
        0x46, 0x4C, 0x56, 0x4D, // Magic: FLVM
        0x01, 0x00,             // Version: 0x0100
        0x00, 0x00,             // Flags: 0x0000
        0x00, 0x00, 0x00, 0x01, // Code size: 1
        0x00, 0x00, 0x00, 0x10, // Code offset: 16
        0x61,                   // HALT opcode
    ];

    let loader = BytecodeLoader::new(&data);
    assert!(loader.is_ok());
}

#[test]
fn test_bytecode_loader_invalid_magic() {
    let data = vec![
        0xFF, 0xFF, 0xFF, 0xFF, // Invalid magic
        0x01, 0x00,
        0x00, 0x00,
        0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x10,
    ];

    let loader = BytecodeLoader::new(&data);
    assert!(loader.is_err());
}

#[test]
fn test_bytecode_loader_too_small() {
    let data = vec![0x01, 0x02, 0x03];
    let loader = BytecodeLoader::new(&data);
    assert!(loader.is_err());
}

// ====== Opcode Tests ======

#[test]
fn test_opcode_push() {
    assert_eq!(Opcode::from_byte(0x01), Some(Opcode::Push));
}

#[test]
fn test_opcode_pop() {
    assert_eq!(Opcode::from_byte(0x02), Some(Opcode::Pop));
}

#[test]
fn test_opcode_halt() {
    assert_eq!(Opcode::from_byte(0x61), Some(Opcode::Halt));
}

#[test]
fn test_opcode_print() {
    assert_eq!(Opcode::from_byte(0x60), Some(Opcode::Print));
}

#[test]
fn test_opcode_invalid() {
    assert_eq!(Opcode::from_byte(0xFF), None);
}

// ====== Memory Tests ======

#[test]
fn test_memory_read_write() {
    let mut mem = Memory::new();
    mem.write(0, 42).unwrap();
    assert_eq!(mem.read(0).unwrap(), 42);
}

#[test]
fn test_memory_multiple_values() {
    let mut mem = Memory::new();
    for i in 0..10 {
        mem.write(i, (i * 2) as u64).unwrap();
    }
    for i in 0..10 {
        assert_eq!(mem.read(i).unwrap(), (i * 2) as u64);
    }
}

#[test]
fn test_memory_out_of_bounds() {
    let mut mem = Memory::new();
    let result = mem.write(20000, 0);
    assert!(result.is_err());
}

#[test]
fn test_memory_stack_operations() {
    let mut mem = Memory::new();
    let mut sp = 0;

    // Push values
    mem.stack_push(&mut sp, 10).unwrap();
    mem.stack_push(&mut sp, 20).unwrap();
    mem.stack_push(&mut sp, 30).unwrap();

    // Pop values (LIFO)
    assert_eq!(mem.stack_pop(&mut sp).unwrap(), 30);
    assert_eq!(mem.stack_pop(&mut sp).unwrap(), 20);
    assert_eq!(mem.stack_pop(&mut sp).unwrap(), 10);
}

// ====== VM Tests ======

#[test]
fn test_vm_creation() {
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, // Magic
        0x01, 0x00,             // Version
        0x00, 0x00,             // Flags
        0x00, 0x00, 0x00, 0x01, // Code size
        0x00, 0x00, 0x00, 0x10, // Code offset
        0x61,                   // HALT
    ];

    let vm = VM::new(&bytecode);
    assert!(vm.is_ok());
}

#[test]
fn test_vm_invalid_bytecode() {
    let bytecode = vec![0xFF, 0xFF];
    let vm = VM::new(&bytecode);
    assert!(vm.is_err());
}

#[test]
fn test_vm_pc_increment() {
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D, // Magic
        0x01, 0x00,             // Version
        0x00, 0x00,             // Flags
        0x00, 0x00, 0x00, 0x01, // Code size
        0x00, 0x00, 0x00, 0x10, // Code offset
        0x61,                   // HALT
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    assert_eq!(vm.pc, 0);

    // PC increments during step (before we implement actual instructions)
    // For now, this will fail with "not implemented"
    let _ = vm.step();
    // Just verify VM was created successfully
}

// ====== PUSH Instruction Tests ======

#[test]
fn test_push_single_value() {
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D,  // Magic
        0x01, 0x00,              // Version
        0x00, 0x00,              // Flags
        0x00, 0x00, 0x00, 0x09,  // Code size: 9
        0x00, 0x00, 0x00, 0x10,  // Code offset: 16
        // PUSH 42
        0x01,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x2A,
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    vm.step().unwrap();  // Execute PUSH
    assert_eq!(vm.sp, 1);  // Stack pointer moved
    assert_eq!(vm.memory.read(0).unwrap(), 42);  // Value on stack
}

#[test]
fn test_push_multiple_values() {
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D,  // Magic
        0x01, 0x00,              // Version
        0x00, 0x00,              // Flags
        0x00, 0x00, 0x00, 0x12,  // Code size: 18
        0x00, 0x00, 0x00, 0x10,  // Code offset: 16
        // PUSH 10
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A,
        // PUSH 20
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x14,
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    vm.step().unwrap();  // PUSH 10
    assert_eq!(vm.sp, 1);
    vm.step().unwrap();  // PUSH 20
    assert_eq!(vm.sp, 2);
    assert_eq!(vm.memory.read(0).unwrap(), 10);
    assert_eq!(vm.memory.read(1).unwrap(), 20);
}

// ====== POP Instruction Tests ======

#[test]
fn test_pop_after_push() {
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D,  // Magic
        0x01, 0x00,              // Version
        0x00, 0x00,              // Flags
        0x00, 0x00, 0x00, 0x0A,  // Code size: 10
        0x00, 0x00, 0x00, 0x10,  // Code offset: 16
        // PUSH 42
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x2A,
        // POP
        0x02,
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    vm.step().unwrap();  // PUSH
    assert_eq!(vm.sp, 1);
    vm.step().unwrap();  // POP
    assert_eq!(vm.sp, 0);
}

#[test]
fn test_pop_empty_stack() {
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D,  // Magic
        0x01, 0x00,              // Version
        0x00, 0x00,              // Flags
        0x00, 0x00, 0x00, 0x01,  // Code size: 1
        0x00, 0x00, 0x00, 0x10,  // Code offset: 16
        0x02,  // POP
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let result = vm.step();
    assert!(result.is_err());  // Should error on empty stack
}

// ====== LOAD/STORE Instruction Tests ======

#[test]
fn test_load_after_store() {
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D,  // Magic
        0x01, 0x00,              // Version
        0x00, 0x00,              // Flags
        0x00, 0x00, 0x00, 0x0C,  // Code size: 12
        0x00, 0x00, 0x00, 0x10,  // Code offset: 16
        // PUSH 42
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x2A,
        // STORE 0
        0x04, 0x00,
        // LOAD 0
        0x03, 0x00,
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    vm.step().unwrap();  // PUSH 42
    assert_eq!(vm.sp, 1);
    vm.step().unwrap();  // STORE 0
    assert_eq!(vm.sp, 0);
    assert_eq!(vm.memory.read(vm.bp).unwrap(), 42);
    vm.step().unwrap();  // LOAD 0
    assert_eq!(vm.sp, 1);
    assert_eq!(vm.memory.read(0).unwrap(), 42);
}

#[test]
fn test_dup_instruction() {
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D,  // Magic
        0x01, 0x00,              // Version
        0x00, 0x00,              // Flags
        0x00, 0x00, 0x00, 0x0A,  // Code size: 10
        0x00, 0x00, 0x00, 0x10,  // Code offset: 16
        // PUSH 42
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x2A,
        // DUP
        0x07,
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    vm.step().unwrap();  // PUSH
    assert_eq!(vm.sp, 1);
    vm.step().unwrap();  // DUP
    assert_eq!(vm.sp, 2);
    assert_eq!(vm.memory.read(0).unwrap(), 42);
    assert_eq!(vm.memory.read(1).unwrap(), 42);
}

#[test]
fn test_swap_instruction() {
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D,  // Magic
        0x01, 0x00,              // Version
        0x00, 0x00,              // Flags
        0x00, 0x00, 0x00, 0x13,  // Code size: 19
        0x00, 0x00, 0x00, 0x10,  // Code offset: 16
        // PUSH 10
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A,
        // PUSH 20
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x14,
        // SWAP
        0x08,
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    vm.step().unwrap();  // PUSH 10
    vm.step().unwrap();  // PUSH 20
    assert_eq!(vm.memory.read(0).unwrap(), 10);
    assert_eq!(vm.memory.read(1).unwrap(), 20);
    vm.step().unwrap();  // SWAP
    assert_eq!(vm.memory.read(0).unwrap(), 20);
    assert_eq!(vm.memory.read(1).unwrap(), 10);
}

// ====== Integration Tests ======

#[test]
fn test_push_store_load_print() {
    // Test: PUSH 42, STORE 0, LOAD 0, PRINT
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D,  // Magic
        0x01, 0x00,              // Version
        0x00, 0x00,              // Flags
        0x00, 0x00, 0x00, 0x0D,  // Code size: 13
        0x00, 0x00, 0x00, 0x10,  // Code offset: 16
        // PUSH 42
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x2A,
        // STORE 0
        0x04, 0x00,
        // LOAD 0
        0x03, 0x00,
        // PRINT
        0x60,
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    vm.step().unwrap();  // PUSH
    vm.step().unwrap();  // STORE
    vm.step().unwrap();  // LOAD
    // Note: PRINT will output, test just verifies no error
    vm.step().unwrap();  // PRINT
}

#[test]
fn test_variable_reassignment() {
    // Test: PUSH 10, STORE 0, PUSH 20, STORE 0, LOAD 0
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D,  // Magic
        0x01, 0x00,              // Version
        0x00, 0x00,              // Flags
        0x00, 0x00, 0x00, 0x16,  // Code size: 22
        0x00, 0x00, 0x00, 0x10,  // Code offset: 16
        // PUSH 10
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A,
        // STORE 0
        0x04, 0x00,
        // PUSH 20
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x14,
        // STORE 0
        0x04, 0x00,
        // LOAD 0
        0x03, 0x00,
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    vm.step().unwrap();  // PUSH 10
    vm.step().unwrap();  // STORE 0 (local[0] = 10)
    assert_eq!(vm.memory.read(vm.bp).unwrap(), 10);

    vm.step().unwrap();  // PUSH 20
    vm.step().unwrap();  // STORE 0 (local[0] = 20, overwrite)
    assert_eq!(vm.memory.read(vm.bp).unwrap(), 20);

    vm.step().unwrap();  // LOAD 0
    assert_eq!(vm.sp, 1);
    assert_eq!(vm.memory.read(0).unwrap(), 20);
}

// ====== Arithmetic Instruction Tests ======

#[test]
fn test_add_basic() {
    // PUSH 10, PUSH 20, ADD
    let bytecode = vec![
        0x46, 0x4C, 0x56, 0x4D,  // Magic
