    // Verify global references updated
    assert!(gc.find_object(globals[0] as usize).is_some());
    assert!(gc.find_object(globals[1] as usize).is_some());
}

#[test]
fn test_fragmentation_calculation() {
    use freelang_vm::gc::ObjectType;

    let mut gc = GarbageCollector::new();
    gc.register_allocation(0x5000, 5, ObjectType::Array(5));
    gc.register_allocation(0x5006, 3, ObjectType::String(3));
    gc.register_allocation(0x5009, 7, ObjectType::Array(7));

    // Mark first and third, free middle
    let stack = [0x5000, 0x5009];
    gc.mark_reachable(&stack, &[]);
    gc.sweep();

    let frag_before = gc.fragmentation_ratio();
    assert!(frag_before > 0.0); // Has fragmentation

    let mut stack_mut = [0x5000, 0x5009];
    let mut globals: [u64; 0] = [];
    gc.compact(&mut stack_mut, &mut globals);

    let frag_after = gc.fragmentation_ratio();
    assert!(frag_after < frag_before); // Reduced fragmentation
}

#[test]
fn test_should_compact_trigger() {
    use freelang_vm::gc::ObjectType;

    let mut gc = GarbageCollector::new();
    // Allocate pattern with significant fragmentation
    for i in 0..5 {
        gc.register_allocation(0x5000 + (i * 10), 8, ObjectType::Array(4));
    }

    // Mark only some, creating fragmentation
    let stack = [0x5000, 0x5018];
    gc.mark_reachable(&stack, &[]);
    gc.sweep();

    // Check if compaction is recommended
    let should_compact = gc.should_compact();
    // Depends on fragmentation threshold, may be true or false
    // Just verify the method works
    let _ = should_compact;
}

#[test]
fn test_bump_pointer_allocation() {
    let mut allocator = freelang_vm::gc::BumpPointerAllocator::new(0x5000, 0xFFFE);

    // Allocate 10 bytes
    let addr1 = allocator.allocate(10).unwrap();
    assert_eq!(addr1, 0x5000);

    // Allocate 5 more
