    allocator.allocate(20).unwrap();
    assert!(allocator.available_space() < (0xFFFE - 0x5000));

    allocator.reset();
    assert_eq!(allocator.available_space(), 0xFFFE - 0x5000);
}

#[test]
fn test_compaction_count() {
