fn test_phase_b_week3_gc_pause_time() {
    use freelang_vm::gc::ObjectType;
    use std::time::Instant;

    let mut gc = GarbageCollector::new();

    // Allocate many objects
    for i in 0..1000 {
        let addr = 0x5000 + (i * 10);
        if addr < 0xFFFE {
            gc.register_allocation(addr, 8, ObjectType::Array(1));
        }
    }

    // Measure GC time
    let start = Instant::now();
    let stack = [0x5000];
    gc.mark_reachable(&stack, &[]);
    gc.sweep();
    let gc_time = start.elapsed();

    // GC should complete quickly (< 100ms for 1000 objects)
