#[test]
fn test_phase_b_week3_combined_workflow() {
    use freelang_vm::gc::ObjectType;

    let mut gc = GarbageCollector::new();

    // Simulate realistic program lifecycle
    // 1. Allocate working set
    for i in 0..100 {
        let addr = 0x5000 + (i * 10);
        if addr < 0xFFFE {
            gc.register_allocation(addr, 8, ObjectType::Array(i as u64));
        }
    }

    let objects_before = gc.heap_objects.len();

    // 2. Mark some as reachable (keep first 50)
    let mut stack = vec![];
    for i in 0..50 {
        stack.push(0x5000 + (i * 10));
    }
    gc.mark_reachable(&stack, &[]);

    // 3. Sweep unreachable
    gc.sweep();

    // 4. Should have ~50 objects left
    let objects_after = gc.allocated_objects_count();
    assert!(objects_after <= objects_before);
    assert!(objects_after > 0);

    // 5. Compact if needed
    if gc.should_compact() {
        gc.compact();
        let compactions = gc.compaction_count();
        assert!(compactions > 0);
    }

    // 6. Verify heap is clean
    assert!(gc.freed_count > 0);
}

