        0x04, 0x00,                                             // STORE 0 (var=15)
        0x03, 0x00,                                             // LOAD 0 (push 15)
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 1);
    assert_eq!(vm.memory.read(0).unwrap(), 15);
}

