        0x46, 0x4C, 0x56, 0x4D, 0x01, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x4C, 0x00, 0x00, 0x00, 0x10,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x05, // PUSH 5 (x)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // PUSH 0
        0x26,                                                   // LT (5 < 0 = 0)
        0x32, 0x00, 0x00, 0x00, 0x40,                         // JIT to skip if false
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0F, // PUSH 15 (y)
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0A, // PUSH 10
        0x26,                                                   // LT (15 < 10 = 0)
        0x32, 0x00, 0x00, 0x00, 0x39,                         // JIT to else
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x64, // PUSH 100 (then)
        0x30, 0x00, 0x00, 0x00, 0x3D,                         // JMP to end
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x32, // PUSH 50 (else)
        0x61, 0x00,                                             // HALT 0
    ];

    let mut vm = VM::new(&bytecode).unwrap();
    let _ = vm.run();
    assert_eq!(vm.sp, 1);
}

